package main
import("encoding/json";"os";"io";"fmt";"verdugo/native/maps/gmaps")
func main(){raw,e:=io.ReadAll(io.LimitReader(os.Stdin,65537));if e!=nil||len(raw)>65536{panic("input")};var rows []json.RawMessage;if json.Unmarshal(raw,&rows)!=nil{panic("json")};out:=[]map[string]any{};for _,r:=range rows{item,e:=gmaps.EntryFromJSON(r);if e!=nil{panic("original parser rejected input")};if item.Validate()!=nil{panic("original validation rejected input")};out=append(out,map[string]any{"review_count":item.ReviewCount,"rating":item.ReviewRating,"categories":len(item.Categories),"website_present":item.WebSite!="","opening_days":len(item.OpenHours)})};result:=map[string]any{"records":out,"google_maps_queried":false,"review_authenticity_verified":false};b,e:=json.Marshal(result);if e!=nil{panic("result")};fmt.Println(string(b))}
